# мессенджер 500 AED, интеграция с учётом от 10 000 AED, BI от 1 000 AED, ИИ-агент от 5 000 AED, лицензии bitrix24.ae
# HubSpot: hubspot.com/pricing/sales на 23.10.2026 (Professional от $90 за место в месяц, обязательный onboarding $1 500, Enterprise $3 500)
LA_DATE = '23 октября 2026'

def la_tbl(head, rows, note=''):
    th = ''.join('<th>' + esc(h) + '</th>' for h in head)
    tr = ''
    for r in rows:
        tr += '<tr><td><b>' + r[0] + '</b></td><td class="pt-p">' + r[1] + '</td>' + ''.join('<td>' + c + '</td>' for c in r[2:]) + '</tr>'
    n = ('<p class="note">' + note + '</p>') if note else ''
    return '<div class="ptw gl"><table class="ptab"><thead><tr>' + th + '</tr></thead><tbody>' + tr + '</tbody></table></div>' + n

def la_mid(h3, text, btn):
    return ('<section class="sec dark"><div class="wrap"><div class="cross"><div><h3>' + esc(h3) + '</h3><p>' + esc(text)
            + '</p></div><a class="btn" href="#form">' + esc(btn) + '</a></div></div></section>')

def LA(path, text): return '<a href="' + U(path) + '">' + text + '</a>'

LA_PRICES = [
    ('Стандартная настройка CRM', 'от ' + nb('10 000') + ' AED', 'до 20 пользователей, запуск от 14 дней'),
    ('Работы сверх стандарта', '200 AED в час', 'смета в AED фиксируется до старта'),
    ('WhatsApp или другой мессенджер', '500 AED', 'подписка провайдера отдельно'),
    ('Интеграция с учётной системой', 'от ' + nb('10 000') + ' AED', 'Zoho Books, QuickBooks, Odoo'),
    ('BI-аналитика', 'от ' + nb('1 000') + ' AED', 'после списка показателей'),
    ('Поддержка после запуска', 'от ' + nb('1 250') + ' AED', 'в месяц, пакет 5 часов'),
    ('Лицензия Битрикс24', 'от 180 AED', 'в месяц, облако Basic при оплате за год, цена bitrix24.ae'),
]
def la_prices(keys=None, extra=None):
    rows = [r for r in LA_PRICES if keys is None or r[0] in keys]
    if extra: rows = extra + rows
    return la_tbl(['Работа', 'Цена', 'Условия'], rows, 'Цены на ' + LA_DATE + ', без VAT. Все цены на странице ' + LA('/ceny', 'цен в AED'))

def la_page(d):
    b = hero(d['eyebrow'], d['h1'], d['lead'], d['answer'], ('#form', d['cta']), ('#price', 'Цены'), d['vis'], d['chips'], d['alt'])
    b += d['sections'][0]
    b += section(d['table_title'], d.get('table_sub', ''), d['table'], id_='price', tone='tint')
    b += la_mid(*d['mid'])
    for s in d['sections'][1:]: b += s
    if d.get('cases'): b += section('Кейсы', 'Реальные проекты MakeBiz', case_cards(d['cases']), tone='tint')
    b += contract_block() + faq(d['faq']) + form_block(d['slug'], d['form'][0], d['form'][1]) + crosslink('ai')
    built.append(page(d['path'], d['slug'], d['title'], d['desc'], 'bitrix', b,
        [service_ld(d['svc'][0], d['svc'][1], d['path'], d['svc'][2])],
        [('/', 'Главная'), ('/bitrix', 'Битрикс24'), (d['path'], d['crumb'])], d['faq']))

